-- 001_init: initial schema.
-- All ids are UUIDv4 strings generated by the server (never autoincrement).
-- All timestamps are INTEGER unix seconds.

CREATE TABLE users (
  id            TEXT PRIMARY KEY,
  email         TEXT NOT NULL UNIQUE COLLATE NOCASE,
  password_hash TEXT NOT NULL,
  is_owner      INTEGER NOT NULL DEFAULT 0 CHECK (is_owner IN (0, 1)),
  created_at    INTEGER NOT NULL DEFAULT (unixepoch())
);
-- At most one owner: the first account created by signup.
CREATE UNIQUE INDEX users_single_owner ON users(is_owner) WHERE is_owner = 1;

CREATE TABLE sessions (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- hash of the random session token sent in the cookie; the raw token is never stored
  token_hash TEXT NOT NULL UNIQUE,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  expires_at INTEGER NOT NULL
);
CREATE INDEX sessions_user_id ON sessions(user_id);

CREATE TABLE known_devices (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- hash of the random device-cookie value; the raw value is never stored
  token_hash   TEXT NOT NULL UNIQUE,
  created_at   INTEGER NOT NULL DEFAULT (unixepoch()),
  last_used_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE INDEX known_devices_user_id ON known_devices(user_id);

CREATE TABLE folders (
  id               TEXT PRIMARY KEY,
  user_id          TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name             TEXT NOT NULL,
  -- NULL = root; deleting a folder deletes its whole subtree
  parent_folder_id TEXT REFERENCES folders(id) ON DELETE CASCADE,
  created_at       INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE INDEX folders_user_id ON folders(user_id);
CREATE INDEX folders_parent_folder_id ON folders(parent_folder_id);

CREATE TABLE notes (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- NULL = root; deleting the folder (at any depth above) deletes the note
  folder_id    TEXT REFERENCES folders(id) ON DELETE CASCADE,
  title        TEXT NOT NULL DEFAULT '',
  -- TipTap JSON document
  content      TEXT NOT NULL DEFAULT '{"type":"doc","content":[]}' CHECK (json_valid(content)),
  -- guards content saves only (optimistic concurrency); renames and moves never change it
  version      INTEGER NOT NULL DEFAULT 1,
  created_at   INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at   INTEGER NOT NULL DEFAULT (unixepoch()),
  share_type   TEXT NOT NULL DEFAULT 'private'
               CHECK (share_type IN ('private', 'password_protected', 'signed_url')),
  -- argon2 hash of the PIN (password_protected) or the signing nonce (signed_url)
  share_secret TEXT,
  expires_at   INTEGER
);
CREATE INDEX notes_user_id ON notes(user_id);
CREATE INDEX notes_folder_id ON notes(folder_id);

-- Attachments belong to the user, not to a note (no note_id).
CREATE TABLE attachments (
  id               TEXT PRIMARY KEY,
  user_id          TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- display only; never used in a filesystem path
  original_name    TEXT NOT NULL,
  -- random on-disk file name under DATA_DIR/uploads
  storage_name     TEXT NOT NULL UNIQUE,
  mime             TEXT NOT NULL,
  size             INTEGER NOT NULL,
  created_at       INTEGER NOT NULL DEFAULT (unixepoch()),
  -- when the attachment last lost a note reference (set by the trigger below)
  last_unlinked_at INTEGER
);
CREATE INDEX attachments_user_id ON attachments(user_id);

-- Which notes reference which attachments; rebuilt from the content on every content save.
CREATE TABLE note_attachments (
  note_id       TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
  attachment_id TEXT NOT NULL REFERENCES attachments(id) ON DELETE CASCADE,
  PRIMARY KEY (note_id, attachment_id)
);
CREATE INDEX note_attachments_attachment_id ON note_attachments(attachment_id);

-- Fires for explicit deletes and for FK cascade deletes (a deleted note, or a folder deleted at any
-- depth above it), so the moment an image loses a reference is always recorded.
CREATE TRIGGER note_attachments_unlinked AFTER DELETE ON note_attachments FOR EACH ROW
BEGIN
  UPDATE attachments SET last_unlinked_at = unixepoch() WHERE id = OLD.attachment_id;
END;
